const viewer = (window.viewer = new Cesium.Viewer("cesiumContainer", {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({
      url: "https://tile.openstreetmap.org/",
      maximumLevel: 18,
    })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

// Procedural canyon-like terrain: high plateau rims with deep central trenches
viewer.terrainProvider = new Cesium.CustomHeightmapTerrainProvider({
  width: 32,
  height: 32,
  callback: function (x, y, level) {
    const W = 32, H = 32;
    const buf = new Float32Array(W * H);
    const scale = Math.pow(2, level);

    for (let row = 0; row < H; row++) {
      for (let col = 0; col < W; col++) {
        // Normalized global tile coordinates
        const gx = (x + col / W) / scale;
        const gy = (y + row / H) / scale;

        // Angular phase values at canyon-scale frequency
        const fx = gx * Math.PI * 128;
        const fy = gy * Math.PI * 128;

        // Plateau base: Grand Canyon South Rim is ~2100 m
        const base = 2100;

        // Two canyon cuts at different orientations — sharp V-profile via sine
        // (1 - |sin|) → 1 at trough (deep cut), 0 at peak (high rim)
        const trench1 = (1.0 - Math.abs(Math.sin(fx * 0.40))) * 3800;
        const trench2 = (1.0 - Math.abs(Math.sin(fy * 0.55 + fx * 0.18))) * 3000;
        // Take the deeper of the two cuts at each sample
        const canyonCut = Math.max(trench1, trench2);

        // Mesa-top ridges and fine-scale buttes
        const ridge = Math.abs(Math.cos(fx * 1.6)) * Math.abs(Math.cos(fy * 0.9)) * 900;
        const fine  = Math.sin(fx * 2.8 - fy * 1.9) * 280;

        // Canyon floor can go well below sea level for dramatic exaggeration
        buf[row * W + col] = base - canyonCut + ridge + fine;
      }
    }
    return buf;
  },
});

// Depth test so terrain self-occludes properly at canyon scale
viewer.scene.globe.depthTestAgainstTerrain = true;

// Enable lighting so ridge/trough shading makes relief legible
viewer.scene.globe.enableLighting = true;

// Angled directional light to cast shadows across canyon walls
viewer.scene.light = new Cesium.DirectionalLight({
  direction: Cesium.Cartesian3.normalize(
    new Cesium.Cartesian3(0.25, -0.55, -0.80),
    new Cesium.Cartesian3()
  ),
  intensity: 2.2,
});

// Boost vertical relief so canyons read clearly from camera altitude
viewer.scene.verticalExaggeration = 3.0;
viewer.scene.verticalExaggerationRelativeHeight = 0.0;

// Atmosphere and fog help depth perception
viewer.scene.fog.enabled = true;
viewer.scene.fog.density = 0.0004;
viewer.scene.skyAtmosphere.show = true;

// Camera: Mather Point, Grand Canyon South Rim — heading due north, pitch -15°
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-112.0473, 36.0613, 7800),
  orientation: {
    heading: Cesium.Math.toRadians(0),    // due north
    pitch:   Cesium.Math.toRadians(-15),  // slight downward look into canyon
    roll:    0.0,
  },
});
